/**
 * Several independent choices, all visible (`design/components/checkbox-group.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/checkbox-group.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/checkbox-group.module.css'

export type CheckboxGroupOrientation = NonNullable<CheckboxGroupProps['orientation']>

export interface CheckboxGroupOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface CheckboxGroupProps {
  'aria-describedby'?: string
  /**
   * Set by FormField, because the group's question is the field's label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string[]
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Set on every box, with each option's `value`, which is the native multi-value form data.
   */
  name?: string
  /**
   * Reports checked values in **options order**, not click order, so the result is stable and
   * comparable. The empty array is a lawful state, unlike Radio's no-null rule, because "none of
   * these" is a real answer to a multi-choice question.
   */
  onChange?: (values: string[]) => void
  /**
   * Items render from data, because free-form children invite custom layouts (Radio's law).
   */
  options: CheckboxGroupOption[]
  /**
   * Horizontal only for ≤3 short labels without descriptions (Radio's guidance, not enforced).
   */
  orientation?: 'horizontal' | 'vertical'
  value?: string[]
}

/** Several independent choices, all visible. */
export default function CheckboxGroup(given: CheckboxGroupProps): JSX.Element {
  const props = mergeProps(
    { orientation: 'vertical', invalid: false, disabled: false } as Defaults<
      CheckboxGroupProps,
      'orientation' | 'invalid' | 'disabled'
    >,
    claimSlot(given, 'group'),
  )
  return scope(() => {
    const uid = createUniqueId()
    const mirror = createCell(props.defaultValue ?? [])
    const group = elementRef<HTMLElement>()
    const current = createDerived(() => props.value ?? mirror.value)
    const toggle = createDerived(
      () => (optionValue: string, checked: boolean) =>
        ((next: string[]) => ((mirror.value = next), props.onChange?.(next)))(
          props.options
            .filter((option) =>
              option.value === optionValue ? checked : current.value.includes(option.value),
            )
            .map((option) => option.value),
        ),
    )
    const choose = createDerived(
      () => (chosen: readonly string[]) =>
        ((next: string[]) =>
          next.length === current.value.length && next.every((each) => current.value.includes(each))
            ? undefined
            : ((mirror.value = next), props.onChange?.(next)))(
          props.options
            .filter((option) =>
              props.disabled || option.disabled === true
                ? current.value.includes(option.value)
                : chosen.includes(option.value),
            )
            .map((option) => option.value),
        ),
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'CheckboxGroup',
        element: () => group.value,
        state: () => ({
          value: current.value,
          options: props.options.map((option) => ({
            id: option.value,
            label: option.label,
            ...(option.disabled === true ? { disabled: true } : {}),
          })),
          disabled: props.disabled,
          invalid: props.invalid,
        }),
        actions: { choose: { argument: 'ids', run: (value) => choose.value(value) } },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <div
        class={styles.group}
        id={props.id}
        role="group"
        data-orientation={props.orientation}
        data-invalid={props.invalid ? '' : undefined}
        data-disabled={props.disabled ? '' : undefined}
        data-required={props['aria-required'] ? '' : undefined}
        aria-label={props['aria-label']}
        aria-labelledby={props['aria-labelledby']}
        aria-describedby={props['aria-describedby']}
        aria-invalid={props.invalid ? true : undefined}
        data-member="checkbox-group"
        ref={group.attach}
      >
        <Each of={props.options} by={(option) => option.value} renew>
          {(option, index) => (
            <div
              class={styles.item}
              data-disabled={props.disabled || option.disabled === true ? '' : undefined}
            >
              {/* row */}
              <label
                class={styles.row}
                data-state={current.value.includes(option.value) ? 'checked' : 'unchecked'}
                data-disabled={props.disabled || option.disabled === true ? '' : undefined}
              >
                {/* box */}
                <button
                  class={styles.box}
                  type="button"
                  role="checkbox"
                  value={option.value}
                  aria-checked={current.value.includes(option.value)}
                  disabled={props.disabled || option.disabled === true}
                  aria-describedby={
                    option.description !== undefined
                      ? `${props.id ?? uid}-option-${index()}-description`
                      : undefined
                  }
                  data-state={current.value.includes(option.value) ? 'checked' : 'unchecked'}
                  data-disabled={props.disabled || option.disabled === true ? '' : undefined}
                  onclick={() => toggle.value(option.value, !current.value.includes(option.value))}
                  onkeydown={($event: KeyboardEvent) =>
                    $event.key === 'Enter' && $event.preventDefault()
                  }
                >
                  {current.value.includes(option.value) ? (
                    <span class={styles.indicator} data-state="checked">
                      <Icon name="confirm" size="sm" />
                    </span>
                  ) : null}
                </button>
                <span class={styles.label}>{option.label}</span>
              </label>
              {option.description !== undefined ? (
                <span
                  class={styles.description}
                  id={`${props.id ?? uid}-option-${index()}-description`}
                >
                  {option.description}
                </span>
              ) : null}
              {props.name !== undefined && current.value.includes(option.value) ? (
                <input type="hidden" name={props.name} value={option.value} />
              ) : null}
            </div>
          )}
        </Each>
      </div>
    )
  })
}

CheckboxGroup.controlKind = 'group'
